const body = $input.first().json.body || $input.first().json;
const query = (body.query || body.question || body.text || '').trim();

if (!query) {
  throw new Error("[KB Error] Câu hỏi không được để trống!");
}

// Tài liệu cẩm nang kỹ thuật nội bộ công ty (Internal IT Knowledge Base)
const internalKnowledgeBase = `
[TÀI LIỆU IT NỘI BỘ - CÔNG TY TNHH CÔNG NGHỆ]
1. Mạng & WiFi:
- WiFi Văn phòng: Tên 'CORP-SECURE', Mật khẩu 'TechCorp@2026!'. Thiết bị phải cài chứng chỉ bảo mật 802.1x.
- VPN Công ty: Truy cập 'vpn.company.com', dùng tài khoản Single Sign-On (SSO) và xác thực 2 bước (MFA) qua Google Authenticator.

2. Máy in & Thiết bị ngoại vi:
- Máy in Tầng 2 (Phòng Kinh Doanh & Kế Toán): IP '192.168.10.250', Driver Canon LBP 2900.
- Máy in Tầng 3 (Phòng Kỹ Thuật & Khối Sáng Tạo): IP '192.168.10.251', Driver HP LaserJet Pro M404dn (Hỗ trợ in 2 mặt tự động).
- Cách kết nối: Vào Control Panel -> Devices and Printers -> Add Printer -> Chọn IP tương ứng.

3. Phần mềm văn phòng & Tài khoản:
- Cài đặt Office 365: Đăng nhập 'portal.office.com' bằng email công ty (@company.com), tải bộ cài Office Installer.
- Quên mật khẩu email/SSO: Truy cập 'id.company.com/recovery' hoặc gửi yêu cầu reset mật khẩu qua hệ thống Helpdesk.
- Cấp quyền phần mềm: Yêu cầu mở ticket trên IT Portal hoặc gửi Access Request.

4. Sự cố máy tính cơ bản:
- Máy bị treo phần mềm: Nhấn Ctrl + Shift + Esc để mở Task Manager -> Chọn ứng dụng đơ -> End Task.
- Màn hình xanh hoặc mất mạng đột ngột: Khởi động lại máy (Restart), cắm lại cáp mạng LAN hoặc tắt bật lại nút WiFi.
`;

return {
  query,
  internalKnowledgeBase,
  askedAt: new Date().toISOString()
};

