parameters.jsCode:
const prev = $('Load Internal IT Docs').first().json;
const aiRaw = $input.first().json;

let text = '';
if (aiRaw.candidates?.[0]?.content?.parts?.[0]?.text) {
  text = aiRaw.candidates[0].content.parts[0].text;
} else {
  text = JSON.stringify(aiRaw);
}

text = text.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    found: true,
    answer: text,
    steps: [],
    sourceSection: "Cẩm nang IT tổng hợp"
  };
}

return {
  query: prev.query,
  found: parsed.found !== false,
  answer: parsed.answer || "Không tìm thấy tài liệu phù hợp. Vui lòng tạo ticket hỗ trợ.",
  steps: parsed.steps || [],
  sourceSection: parsed.sourceSection || "Tài liệu nội bộ"
};
